from lib import *
S = SS('n13')
steps = [
    step("ServeHTTP 只做 6 件事:第一次调用时用 sync.Once 跑 updateRouteTrees;从 pool 里取一个 Context;把 ResponseWriter 和 Request 装进去;c.reset() 清掉上一个请求留下的字段;handleHTTPRequest(c);放回 pool。handleHTTPRequest 里:选好要匹配的路径(默认 URL.Path)→ 找该方法的树 → getValue → 命中就设 c.handlers 和 fullPath,c.Next() 跑完整条链,最后 WriteHeaderNow()。", t=tl(S(1)), mark=lidx(S(1), 'engine.pool.Get()', 'c.reset()', 'engine.handleHTTPRequest(c)', 'engine.pool.Put(c)'), done=lidx(S(1), 'routeTreesUpdated.Do', 'c.Next()', 'c.writermem.WriteHeaderNow()', 'value := root.getValue'), kv=KV([['取', 'pool.Get() 拿 Context'], ['清', 'c.reset() 清请求相关字段'], ['跑', 'handleHTTPRequest:查树 → Next()'], ['还', 'pool.Put(c)']], ['清'])),
    step("串行发 3 个请求,三次拿到同一个 Context(地址相同),但每次进入 handler 时 Keys 是空的(map[])、Errors 为 0、Params 是本次请求的——reset 把 Keys 置 nil、Errors 截成 0 长度、Params 截成 0 长度。请求结束后如果还拿着第 1 个请求的 Context 指针去读,读到的是第 3 个请求的数据(Keys=map[secret:来自请求 c]、Errors=1、Params=[{id c}])。", t=tl(S(2)), mark=lidx(S(2), '三次请求是否同一个 Context: true', '已经是第 3 个请求的了', 'c.Keys = nil', 'c.Errors = c.Errors[:0]'), done=lidx(S(2), '进入时 Keys=map[] Errors=0'), kv=KV([['同一个指针', '串行请求复用同一个 Context'], ['进入时', 'Keys、Errors、Params 都是干净的'], ['请求结束后', '指针还在,里面是别的请求的数据']], ['请求结束后'])),
    step("每个请求的内存分配(ServeHTTP + 丢弃输出的 writer):静态路由、1 个参数、3 个参数、通配、404、c.Status(204)、3 个空中间件,全是 0;c.String(200, \"hello\") 1 次;c.JSON(200, gin.H{\"a\":1}) 9 次;gin.Default()(Logger + Recovery,Logger 输出丢弃)+ 空 handler 10 次。路由和 Context 复用本身不分配。", t=tl(S(3)), mark=lidx(S(3), 'c.JSON', 'gin.Default()', 'c.String'), done=lidx(S(3), '静态路由,空 handler', '3 个参数', '通配', '3 个空中间件'), b=bars([['静态 / 参数 / 通配 / 404 / 中间件', 0, '0 次'], ['c.String', 1, '1 次'], ['c.JSON', 9, '9 次'], ['Default() + 空 handler', 10, '10 次']], 10, done=[0], mark=[1, 2, 3]), kv=KV([['路由匹配', '0 次分配'], ['c.JSON(gin.H)', '9 次(含 map 与序列化)'], ['Logger + Recovery', '10 次/请求(空 handler)']], ['路由匹配'])),
    step("handler 链跑完,handleHTTPRequest 调 WriteHeaderNow 把还没发出的状态行补发:什么都不写 → 200;c.Status(201) → 201;只设响应头 → 200 且 X-A=1 在响应里;先写了正文再 c.Status(500) → 已经发出的 200 不会改,正文是“先写正文”。", t=tl(S(4)), mark=lidx(S(4), '/status', '/after'), done=lidx(S(4), '/nothing', '/header'), kv=KV([['不写', '200'], ['c.Status(201)', '201,即使没有正文'], ['先写正文再改状态', '改不了,仍是 200']], ['先写正文再改状态'])),
    step("updateRouteTrees 只在第一次 ServeHTTP 时跑一次(sync.Once),把节点里的转义冒号 \\: 还原成 :。注册 /v1/\\:action 之后,第一次请求前路由表里的路径是 \"/v1/\\\\:action\"(%q 打印),第一次请求后变成 \"/v1/:action\";GET /v1/:action 命中(200),GET /v1/other 是 404——\\: 是字面量冒号,不是参数。", t=tl(S(5)), mark=lidx(S(5), '第一次请求前 路由表:"/v1/\\\\:action"', 'GET /v1/other'), done=lidx(S(5), '第一次请求后 路由表:"/v1/:action"', 'GET /v1/:action → 200', 'n.path = strings.ReplaceAll'), kv=KV([['\\:', '字面量冒号'], ['还原时机', '第一次 ServeHTTP(sync.Once)'], ['之前', 'Routes() 看到的还带反斜杠']], ['还原时机'])),
]
A = mkartn('n13', 13, 'Gin,ServeHTTP,Context,sync.Pool,handleHTTPRequest,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 Engine.ServeHTTP 的完整流程:sync.Once 做一次路由树更新、从 pool 取 Context、reset、handleHTTPRequest、放回 pool;连续请求复用同一个 Context 但字段被清空;路由匹配 0 次内存分配,c.JSON 9 次;handler 链结束后补发状态行;转义冒号在第一次请求时才还原。',
    '一个请求进入 Gin,到底经过了哪几步?这篇从 ServeHTTP 的源码开始,用实验验证每一步:Context 是不是真的复用、reset 清了什么、每次请求分配多少内存、状态行什么时候发出,以及第一次请求时被悄悄执行的那一步。',
    [('0 次', '静态、参数、通配路由的一次 ServeHTTP 的内存分配'), ('1 个', '连续 3 个请求用到的 Context 对象个数'), ('9 次', 'c.JSON(200, gin.H{"a":1}) 的内存分配')],
    [('六步骨架', '<p><code>ServeHTTP</code> 的代码不到二十行:第一次调用时用 <code>sync.Once</code> 执行 <code>updateRouteTrees</code>,然后从 <code>sync.Pool</code> 取 Context、绑定 writer 和 request、<code>reset</code>、<code>handleHTTPRequest</code>、放回 pool。<code>handleHTTPRequest</code> 负责选路径、在对应方法的树里查找、命中就跑完 handler 链,没命中则走重定向、405 或 404(前面几篇已经分别验证过)。</p>'),
     ('Context 复用与 reset', '<p>串行请求拿到的是同一个 Context。<code>reset</code> 把 <code>Keys</code>、<code>Errors</code>、<code>Params</code>、查询与表单缓存等全部清掉,所以不会有数据泄漏到下一个请求——但这也意味着请求结束后任何还持有这个指针的 goroutine 读到的都是别的请求的数据。要在 goroutine 里用,必须先 <code>c.Copy()</code>(后面专门验证)。</p>'),
     ('分配次数', '<p>路由匹配本身不分配:静态、参数、通配、404、空中间件,每个请求都是 0 次分配。分配来自 handler 自己:<code>c.String</code> 1 次,<code>c.JSON</code> 9 次(包含 <code>gin.H</code> 这个 map 和序列化)。带 Logger 和 Recovery 的 <code>gin.Default()</code> 即使 handler 为空,每个请求也有 10 次分配,主要来自 Logger 格式化日志。</p>'),
     ('状态行什么时候发出', '<p>handler 链结束后 <code>WriteHeaderNow</code> 才把还没发出的状态行补上,所以 <code>c.Status(201)</code> 不写正文也能让客户端看到 201,什么都不做是默认的 200。反过来,一旦已经写了正文,状态行就发出去了,之后再 <code>c.Status(500)</code> 无效。</p>'),
     ('第一次请求时的 updateRouteTrees', '<p>路由里用 <code>\\:</code> 转义的冒号在注册时保留反斜杠,避免被当成参数;第一次 <code>ServeHTTP</code> 时才统一还原成 <code>:</code>,所以在第一次请求之前读 <code>Routes()</code> 会看到带反斜杠的路径。这样的路由匹配的是字面量的冒号,比如 <code>/v1/:action</code>。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 直接调用 ServeHTTP;分配次数是 testing.AllocsPerRun(2000 次平均,向下取整)测的,writer 是丢弃输出的自定义实现,Default() 的 Logger 输出被设为 io.Discard;每种情形各一次',
     '没有验证:真实 http.Server 下每个请求的分配(net/http 本身会分配);并发请求时 pool 的复用率与 GC 对 pool 的清空影响;c.JSON 的 9 次分配各自来自哪里(没有逐个定位);Logger 的 10 次分配的具体来源'],
    '请求流程')
